1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.jspecify.annotations.Nullable;
5	import org.mapstruct.Mapper;
6	import org.mapstruct.Mapping;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(locality(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
31	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Derives the owner's {@code ageBand} from its birthDate relative to the registrationDate:
36	     * {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and {@code SENIOR} when 65 or older.
37	     * Returns {@code null} when the owner has no birthDate or no registrationDate.
38	     */
39	    default OwnerDto.@Nullable AgeBandEnum ageBand(@Nullable Owner owner) {
40	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
41	            return null;
42	        }
43	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
44	        if (age < 18) {
45	            return OwnerDto.AgeBandEnum.MINOR;
46	        }
47	        if (age < 65) {
48	            return OwnerDto.AgeBandEnum.ADULT;
49	        }
50	        return OwnerDto.AgeBandEnum.SENIOR;
51	    }
52	
53	    /**
54	     * Derives the owner's duplicate-detection {@code identityKey}, formatted as
55	     * {@code normalizedTelephone + '|' + email + '|' + householdId} with an empty email segment when
56	     * the owner has no email. This is the same key the create endpoint uses to reject an owner whose
57	     * whole key equals an existing owner's.
58	     */
59	    default @Nullable String identityKey(@Nullable Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
64	        String email = owner.getEmail() == null ? "" : owner.getEmail();
65	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
66	        return telephone + "|" + email + "|" + householdId;
67	    }
68	
69	    /**
70	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
71	     * otherwise {@code PHONE}.
72	     */
73	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
74	        if (owner == null) {
75	            return null;
76	        }
77	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
78	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
79	    }
80	
81	    /**
82	     * Derives the owner's locality from its region-and-hash identity: the {@code REGION} prefix of
83	     * the {@code customerCode} ({@code '<REGION>-<HASH8>'}), which is the region code derived from
84	     * the postcode on create. Returns the canonical region string, or {@code 'UNKNOWN'} when the
85	     * owner has no customerCode.
86	     */
87	    default @Nullable String locality(@Nullable Owner owner) {
88	        if (owner == null) {
89	            return null;
90	        }
91	        String customerCode = owner.getCustomerCode();
92	        if (customerCode == null) {
